/// Hidden Gem (colorless Skill, Self, EXHAUST). Increase the
/// HiddenGem (colorless Power, 1 energy, Self, EXHAUST). Bumps the
/// `base_replay_count` of a random playable Attack/Skill/Power in the
/// draw pile by `effect_vars.replay` (=2; upgraded form passes 4 via
/// the spec layer once the upgrade surface lands). Mirrors Python pin
/// `sts2-rl-agent@01c094d:sts2_env/cards/colorless.py:551-560`. The
/// per-card-instance `base_replay_count: i32` field landed in bead
/// `sts2-rs-6ynt.8.4` (combat_loop.rs play_count = 1 + extra_plays +
/// card.base_replay_count). If no Attack/Skill/Power is playable in
/// the draw pile, falls back to "any playable card" per the Python
/// pin's two-tier filter; if both tiers come up empty, no-op.
pub(crate) fn play_hidden_gem(state: &mut CombatState, _t: Option<CreatureUid>) -> EffectResult {
    use sts2_core::cards::CardType;

    let playable_filter = |uid: &CardUid| -> bool {
        let idx = uid.0.get() as usize - 1;
        !sts2_core::card_effects::card_unplayable(state.cards[idx].card_id)
    };
    let typed_filter = |uid: &CardUid| -> bool {
        let idx = uid.0.get() as usize - 1;
        matches!(
            state.cards[idx].card_type,
            CardType::Attack | CardType::Skill | CardType::Power,
        )
    };
    // C# `HiddenGem.cs:45` filters the primary pool to cards with
    // `GetEnchantedReplayCount() < 1`; omitting it lets already-enchanted
    // cards into the pool, changing pool size → `next_int_exclusive` RNG
    // desync. Bead `sts2-rs-7pg9x` (OWL_MAGISTRATE_NORMAL_Q).
    let enchanted_replay_filter = |uid: &CardUid| -> bool {
        let idx = uid.0.get() as usize - 1;
        state.cards[idx].base_replay_count == 0
    };
    let primary: SmallVec<[CardUid; 16]> = state
        .player
        .draw
        .iter()
        .copied()
        .filter(playable_filter)
        .filter(typed_filter)
        .filter(enchanted_replay_filter)
        .collect();
    // C# `HiddenGem.cs:35-46` fallback (`list2`) is NOT "any playable card":
    // it is playable AND not Curse/Quest AND `GetEnchantedReplayCount() < 1`.
    // (`list3`/primary further narrows to Attack/Skill/Power.) The prior RS
    // fallback applied only `playable_filter`, so it admitted Status/Curse and
    // already-enchanted cards — inflating the pool and desyncing the
    // `combat_card_selection` read. Bead `sts2-rs-7pg9x` follow-up (sweep
    // 49aeb, seed 2460).
    // The fallback's `(uint)(type - 5) <= 1u` excludes CardType 5 and 6,
    // which are Curse and Quest (CardType.cs: Status = 4), so a playable
    // Status such as FranticEscape stays in the pool (decomp HiddenGem.cs:41,
    // identical in v0.107.1 and v0.111.0). With only a FranticEscape left in
    // the draw pile C# picks it and reads combat_card_selection; Rust read
    // nothing (Silent mid seed 1026, THE_INSATIABLE_BOSS). Both builds
    // (GH #806). Rust has no Quest card type, so only Curse is excluded here.
    let not_curse_quest = |uid: &CardUid| -> bool {
        let idx = uid.0.get() as usize - 1;
        state.cards[idx].card_type != CardType::Curse
    };
    let fallback: SmallVec<[CardUid; 16]> = if primary.is_empty() {
        state
            .player
            .draw
            .iter()
            .copied()
            .filter(playable_filter)
            .filter(not_curse_quest)
            .filter(enchanted_replay_filter)
            .collect()
    } else {
        SmallVec::new()
    };
    let pool: &[CardUid] = if primary.is_empty() {
        &fallback
    } else {
        &primary
    };
    if pool.is_empty() {
        return EffectResult::Resolved;
    }
    let picked = pool[state
        .run_rng
        .combat_card_selection
        .next_int_exclusive(0, pool.len() as i32) as usize];
    let idx = picked.0.get() as usize - 1;
    // C# `HiddenGem.cs:57` adds `DynamicVars["Replay"].IntValue` to the
    // picked card's `BaseReplayCount`; `CanonicalVars` defines
    // `IntVar("Replay", 2)` and `OnUpgrade` calls
    // `UpgradeValueBy(1m)` → 3 upgraded. Bead `sts2-rs-i9wg8` (was
    // `sts2-rs-6ynt.8.4` placeholder constant of 2).
    let replays = if current_upgraded(state) {
        HIDDEN_GEM_REPLAY_UPGRADED
    } else {
        HIDDEN_GEM_REPLAY
    };
    state.cards[idx].base_replay_count = state.cards[idx].base_replay_count.saturating_add(replays);
    EffectResult::Resolved
}

